values ((select id from guides where slug = $pb$neumaticos-turismo-205-55-r16$pb$), 1, $pb$Michelin Primacy 5$pb$, $pb$Mejor en general$pb$, $pb$El Primacy 5 es la gama de confort y seguridad de Michelin para turismos, y en esta medida tiene una de las etiquetas más equilibradas de la guía: B en eficiencia energética, A en agarre en mojado y 70 dB de ruido exterior. Es una opción premium pensada para quien quiere un neumático que funcione bien en cualquier situación sin tener que darle muchas vueltas. La pega: está en la parte alta de precio de la lista y no es el más silencioso según la etiqueta.$pb$, array[$pb$A en agarre en mojado según la etiqueta UE$pb$, $pb$B en eficiencia energética, por encima de varios rivales$pb$, $pb$Gama premium orientada al confort y la seguridad$pb$]::text[], array[$pb$De los más caros de la guía$pb$, $pb$70 dB, un decibelio por encima de los más silenciosos$pb$]::text[], $pb$[{"label":"Medida de referencia","value":"205/55 R16"},{"label":"Eficiencia energética (etiqueta UE)","value":"B"},{"label":"Agarre en mojado (etiqueta UE)","value":"A"},{"label":"Ruido exterior","value":"70 dB"},{"label":"Temporada","value":"Verano"}]$pb$::jsonb);
