values ((select id from guides where slug = $pb$neumaticos-turismo-205-55-r16$pb$), 2, $pb$Bridgestone Turanza 6$pb$, $pb$Mejor relación calidad-precio$pb$, $pb$El Turanza 6 es el neumático de turismo de gama alta de Bridgestone, y en la 205/55 R16 tiene una etiqueta muy completa: B en eficiencia, A en mojado y 69 dB, que es el ruido más bajo de la lista, empatado con otros dos modelos. Lo interesante es que suele venderse por debajo de Michelin y Continental, así que te da una etiqueta de nivel premium sin pagar lo máximo. La pega: no tiene una A en eficiencia, y el ahorro frente a los otros premium varía según la tienda.$pb$, array[$pb$B/A con 69 dB, la mejor combinación de la guía junto al Goodyear$pb$, $pb$Suele costar menos que los otros premium$pb$, $pb$Gama alta de una marca premium$pb$]::text[], array[$pb$Sin A en eficiencia energética$pb$, $pb$El ahorro frente a Michelin y Continental varía según la tienda$pb$]::text[], $pb$[{"label":"Medida de referencia","value":"205/55 R16"},{"label":"Eficiencia energética (etiqueta UE)","value":"B"},{"label":"Agarre en mojado (etiqueta UE)","value":"A"},{"label":"Ruido exterior","value":"69 dB"},{"label":"Temporada","value":"Verano"}]$pb$::jsonb);
