values ((select id from guides where slug = $pb$neumaticos-turismo-205-55-r16$pb$), 3, $pb$Goodyear EfficientGrip Performance 2$pb$, $pb$Para hacer muchos kilómetros$pb$, $pb$Según Goodyear, la gama EfficientGrip se orienta a la eficiencia y a la duración, lo que encaja con quien hace muchos trayectos por autovía. En esta medida la referencia principal tiene B en eficiencia, A en mojado y 69 dB, y algunas variantes llegan a una A en eficiencia, aunque otras bajan a una C. La pega: tienes que mirar bien la etiqueta de la referencia exacta que compras, porque no todas son iguales.$pb$, array[$pb$A en agarre en mojado y 69 dB en todas las variantes$pb$, $pb$Algunas variantes llegan a una A en eficiencia$pb$, $pb$Gama enfocada a la eficiencia y la duración$pb$]::text[], array[$pb$La clase de eficiencia varía entre A y C según la variante$pb$, $pb$No es el más barato de la guía$pb$]::text[], $pb$[{"label":"Medida de referencia","value":"205/55 R16"},{"label":"Eficiencia energética (etiqueta UE)","value":"B (entre A y C según la variante)"},{"label":"Agarre en mojado (etiqueta UE)","value":"A"},{"label":"Ruido exterior","value":"69 dB"},{"label":"Temporada","value":"Verano"}]$pb$::jsonb);
