insert into guide_items (guide_id, position, name, award, summary_md, pros, cons, specs)
values ((select id from guides where slug = $pb$neumaticos-turismo-205-55-r16$pb$), 5, $pb$Hankook Ventus Prime 4$pb$, $pb$La opción económica$pb$, $pb$Hankook es una marca intermedia muy asentada en Europa, y el Ventus Prime 4 es su neumático de verano para turismos de uso diario. Es el más asequible de la guía y aun así tiene una A en agarre en mojado y 69 dB, empatado con los más silenciosos de la lista. Es una buena elección si haces pocos kilómetros al año o usas el coche sobre todo en ciudad. La pega: la C en eficiencia energética implica algo más de consumo que los modelos con B.$pb$, array[$pb$El más asequible de la guía$pb$, $pb$A en agarre en mojado según la etiqueta UE$pb$, $pb$69 dB, entre los más silenciosos de la lista$pb$]::text[], array[$pb$C en eficiencia energética$pb$, $pb$Marca intermedia, con menos prestigio que las premium$pb$]::text[], $pb$[{"label":"Medida de referencia","value":"205/55 R16"},{"label":"Eficiencia energética (etiqueta UE)","value":"C"},{"label":"Agarre en mojado (etiqueta UE)","value":"A"},{"label":"Ruido exterior","value":"69 dB"},{"label":"Temporada","value":"Verano"}]$pb$::jsonb);
