values ((select id from guides where slug = $pb$neumaticos-suv-235-55-r18$pb$), 1, $pb$Bridgestone Turanza 6$pb$, $pb$Mejor en general$pb$, $pb$El Turanza 6 es el neumático de gama alta de Bridgestone para turismos y SUV, y en la 235/55 R18 tiene la etiqueta más equilibrada de la guía: B en eficiencia energética, A en agarre en mojado y 69 dB, el ruido más bajo de la lista junto al del Michelin. Además, suele venderse por debajo de Michelin y Continental, lo que lo convierte en una compra muy razonable para un SUV de uso familiar. La pega: no llega a la A en eficiencia, algo que en un coche pesado se nota en el consumo.$pb$, array[$pb$A en agarre en mojado y B en eficiencia energética$pb$, $pb$69 dB, el ruido más bajo de la lista junto al Michelin$pb$, $pb$Suele costar menos que los otros premium$pb$]::text[], array[$pb$Sin A en eficiencia energética$pb$, $pb$No es el más barato de la guía$pb$]::text[], $pb$[{"label":"Medida de referencia","value":"235/55 R18"},{"label":"Eficiencia energética (etiqueta UE)","value":"B"},{"label":"Agarre en mojado (etiqueta UE)","value":"A"},{"label":"Ruido exterior","value":"69 dB"},{"label":"Temporada","value":"Verano"}]$pb$::jsonb);
