values ((select i.id from guide_items i where i.guide_id = (select id from guides where slug = $pb$neumaticos-suv-235-55-r18$pb$) and i.position = 1), $pb$neumaticos$pb$, $pb$bridgestone-235-55-18-turanza_6$pb$, $pb$https://www.neumaticos.es/neumaticos/bridgestone-235-55-18-turanza_6/108+200+201+202+205$pb$, $pb$Precio para 235/55 R18$pb$, 0);
