values ((select id from guides where slug = $pb$neumaticos-suv-235-55-r18$pb$), 2, $pb$Michelin Primacy 4$pb$, $pb$El de menor consumo según la etiqueta$pb$, $pb$El Primacy 4 es la generación anterior de la gama de confort de Michelin, pero sigue muy presente en medidas de SUV. Es el único de la guía con una A en eficiencia energética, algo interesante en un coche pesado o en un SUV híbrido o eléctrico, y su ruido se queda en 69 dB. Es una opción premium para quien hace muchos kilómetros y quiere gastar menos. La pega: tiene una B en agarre en mojado, la única de la lista, y es de los más caros.$pb$, array[$pb$A en eficiencia energética, la única de la guía$pb$, $pb$69 dB, entre los más silenciosos de la lista$pb$, $pb$Gama premium orientada al confort$pb$]::text[], array[$pb$B en agarre en mojado, por debajo del resto$pb$, $pb$Es el más caro de la guía$pb$]::text[], $pb$[{"label":"Medida de referencia","value":"235/55 R18"},{"label":"Eficiencia energética (etiqueta UE)","value":"A"},{"label":"Agarre en mojado (etiqueta UE)","value":"B"},{"label":"Ruido exterior","value":"69 dB"},{"label":"Temporada","value":"Verano"}]$pb$::jsonb);
