values ((select i.id from guide_items i where i.guide_id = (select id from guides where slug = $pb$neumaticos-suv-235-55-r18$pb$) and i.position = 2), $pb$neumaticos$pb$, $pb$michelin-235-55-18-primacy_4$pb$, $pb$https://www.neumaticos.es/neumaticos/michelin-235-55-18-primacy_4/108+200+201+202+205$pb$, $pb$Precio para 235/55 R18$pb$, 0);
