values ((select id from guides where slug = $pb$neumaticos-suv-235-55-r18$pb$), 3, $pb$Goodyear EfficientGrip 2 SUV$pb$, $pb$Gama específica para SUV$pb$, $pb$A diferencia de los otros modelos premium de la lista, este Goodyear pertenece a una gama desarrollada específicamente para SUV, dentro de la familia EfficientGrip, orientada a la eficiencia. En esta medida tiene B en eficiencia energética, A en agarre en mojado y 70 dB. Es una alternativa sólida si prefieres un neumático concebido para el peso y el uso de un SUV. La pega: su etiqueta es muy parecida a la del Bridgestone y suele costar más.$pb$, array[$pb$Gama diseñada específicamente para SUV$pb$, $pb$A en agarre en mojado según la etiqueta UE$pb$, $pb$B en eficiencia energética$pb$]::text[], array[$pb$70 dB, un decibelio por encima de los más silenciosos$pb$, $pb$Suele costar más que el Bridgestone$pb$]::text[], $pb$[{"label":"Medida de referencia","value":"235/55 R18"},{"label":"Eficiencia energética (etiqueta UE)","value":"B"},{"label":"Agarre en mojado (etiqueta UE)","value":"A"},{"label":"Ruido exterior","value":"70 dB"},{"label":"Temporada","value":"Verano"}]$pb$::jsonb);
