values ((select i.id from guide_items i where i.guide_id = (select id from guides where slug = $pb$neumaticos-suv-235-55-r18$pb$) and i.position = 3), $pb$neumaticos$pb$, $pb$goodyear-235-55-18-efficientgrip_2_suv$pb$, $pb$https://www.neumaticos.es/neumaticos/goodyear-235-55-18-efficientgrip_2_suv/108+200+201+202+205$pb$, $pb$Precio para 235/55 R18$pb$, 0);
