values ((select id from guides where slug = $pb$neumaticos-suv-235-55-r18$pb$), 4, $pb$Continental PremiumContact 7$pb$, $pb$Para una conducción más dinámica$pb$, $pb$El PremiumContact 7 es el neumático premium de Continental para turismos y SUV, con un enfoque más dinámico que el de los modelos de confort de esta lista. En la 235/55 R18 tiene una A en agarre en mojado, pero una C en eficiencia energética y 71 dB, o 72 dB en la versión XL. Es una opción para quien da prioridad al comportamiento del coche y confía en la marca. La pega: sobre el papel consume y suena algo más que sus rivales premium.$pb$, array[$pb$A en agarre en mojado según la etiqueta UE$pb$, $pb$Gama premium con enfoque dinámico$pb$, $pb$Disponible en versión normal y XL$pb$]::text[], array[$pb$C en eficiencia energética$pb$, $pb$71 dB, o 72 dB en la versión XL$pb$]::text[], $pb$[{"label":"Medida de referencia","value":"235/55 R18"},{"label":"Eficiencia energética (etiqueta UE)","value":"C"},{"label":"Agarre en mojado (etiqueta UE)","value":"A"},{"label":"Ruido exterior","value":"71 dB (72 dB en la versión XL)"},{"label":"Temporada","value":"Verano"}]$pb$::jsonb);
