values ((select i.id from guide_items i where i.guide_id = (select id from guides where slug = $pb$neumaticos-suv-235-55-r18$pb$) and i.position = 4), $pb$neumaticos$pb$, $pb$continental-235-55-18-premiumcontact_7$pb$, $pb$https://www.neumaticos.es/neumaticos/continental-235-55-18-premiumcontact_7/108+200+201+202+205$pb$, $pb$Precio para 235/55 R18$pb$, 0);
insert into guide_items (guide_id, position, name, award, summary_md, pros, cons, specs)
values ((select id from guides where slug = $pb$neumaticos-suv-235-55-r18$pb$), 5, $pb$Nexen N'Fera Sport SUV$pb$, $pb$La opción económica$pb$, $pb$Nexen es una marca económica coreana, y el N'Fera Sport SUV es su neumático de verano para SUV. Es el más asequible de la guía y su referencia principal tiene una A en agarre en mojado, aunque alguna variante baja a una B. Tiene sentido si haces pocos kilómetros al año y quieres que el cambio de cuatro ruedas no se dispare. La pega: tiene una D en eficiencia energética, la peor de la lista, y 71 dB de ruido.$pb$, array[$pb$El más asequible de la guía$pb$, $pb$A en agarre en mojado en la referencia principal$pb$, $pb$Diseñado para SUV$pb$]::text[], array[$pb$D en eficiencia energética, la más baja de la guía$pb$, $pb$71 dB, entre los más ruidosos de la lista$pb$]::text[], $pb$[{"label":"Medida de referencia","value":"235/55 R18"},{"label":"Eficiencia energética (etiqueta UE)","value":"D"},{"label":"Agarre en mojado (etiqueta UE)","value":"A (B en alguna variante)"},{"label":"Ruido exterior","value":"71 dB"},{"label":"Temporada","value":"Verano"}]$pb$::jsonb);
