insert into guide_items (guide_id, position, name, award, summary_md, pros, cons, specs)
values ((select id from guides where slug = $pb$neumaticos-invierno$pb$), 1, $pb$Continental WinterContact TS 870$pb$, $pb$Mejor en general$pb$, $pb$Un neumático de invierno de marca premium que cuadra bien para la mayoría de compactos. En la etiqueta UE saca una C en eficiencia energética y una B en agarre en mojado, con 70 dB de ruido exterior, que es lo habitual en esta categoría. Lleva el marcaje 3PMSF, así que está homologado para nieve. Es la opción sensata si haces muchos kilómetros en invierno y no quieres complicarte. La pega: la clase C en eficiencia y que, como modelo premium, no es de los más baratos de la lista.$pb$, array[$pb$Marca premium con buen posicionamiento en invierno$pb$, $pb$Clase B en agarre en mojado$pb$, $pb$Marcaje 3PMSF homologado para nieve$pb$]::text[], array[$pb$Clase C en eficiencia energética$pb$, $pb$Precio de gama premium$pb$]::text[], $pb$[{"label":"Medida de referencia","value":"205/55 R16"},{"label":"Eficiencia energética (etiqueta UE)","value":"C"},{"label":"Agarre en mojado (etiqueta UE)","value":"B"},{"label":"Ruido exterior","value":"70 dB"},{"label":"Temporada","value":"Invierno"},{"label":"Marcaje 3PMSF","value":"Sí"}]$pb$::jsonb);
