values ((select i.id from guide_items i where i.guide_id = (select id from guides where slug = $pb$neumaticos-invierno$pb$) and i.position = 1), $pb$neumaticos$pb$, $pb$continental-205-55-16-wintercontact_ts_870$pb$, $pb$https://www.neumaticos.es/neumaticos/continental-205-55-16-wintercontact_ts_870/108+200+201+202+205$pb$, $pb$Precio para 205/55 R16$pb$, 0);
insert into guide_items (guide_id, position, name, award, summary_md, pros, cons, specs)
values ((select id from guides where slug = $pb$neumaticos-invierno$pb$), 2, $pb$Michelin Alpin 7$pb$, $pb$La opción premium$pb$, $pb$El neumático de invierno de Michelin para turismos, y aquí pagas sobre todo la marca y su posicionamiento en la gama alta. Su etiqueta UE es casi idéntica a la del resto de premium de la guía: C en eficiencia, B en agarre en mojado y 71 dB, un decibelio por encima de los demás. Lleva el marcaje 3PMSF. Encaja si ya confías en la marca y vas a recorrer muchos kilómetros en invierno. La pega: es el más caro de la lista y la etiqueta no le da ventaja clara sobre sus rivales directos.$pb$, array[$pb$Marca de posicionamiento premium$pb$, $pb$Clase B en agarre en mojado$pb$, $pb$Marcaje 3PMSF homologado para nieve$pb$]::text[], array[$pb$71 dB, el más ruidoso de la guía según la etiqueta$pb$, $pb$Clase C en eficiencia y precio alto$pb$]::text[], $pb$[{"label":"Medida de referencia","value":"205/55 R16"},{"label":"Eficiencia energética (etiqueta UE)","value":"C"},{"label":"Agarre en mojado (etiqueta UE)","value":"B"},{"label":"Ruido exterior","value":"71 dB"},{"label":"Temporada","value":"Invierno"},{"label":"Marcaje 3PMSF","value":"Sí"}]$pb$::jsonb);
insert into guide_item_stores (guide_item_id, store, external_id, url, note, position)
values ((select i.id from guide_items i where i.guide_id = (select id from guides where slug = $pb$neumaticos-invierno$pb$) and i.position = 2), $pb$neumaticos$pb$, $pb$michelin-205-55-16-alpin_7$pb$, $pb$https://www.neumaticos.es/neumaticos/michelin-205-55-16-alpin_7/108+200+201+202+205$pb$, $pb$Precio para 205/55 R16$pb$, 0);
insert into guide_items (guide_id, position, name, award, summary_md, pros, cons, specs)
values ((select id from guides where slug = $pb$neumaticos-invierno$pb$), 3, $pb$Bridgestone Blizzak 6$pb$, $pb$Mejor relación calidad-precio$pb$, $pb$Si quieres una marca de primera línea sin pagar lo que cuestan Michelin o Continental, el Blizzak 6 es la alternativa más directa. Su etiqueta UE es la misma que la del Continental: C en eficiencia energética, B en agarre en mojado y 70 dB de ruido exterior. Lleva el marcaje 3PMSF, así que sirve como alternativa a las cadenas cuando la señalización lo permite. Es una compra muy razonable para quien sube a la sierra varias veces por temporada. La pega: la clase C en eficiencia.$pb$, array[$pb$Marca premium a un precio por debajo de sus rivales directos$pb$, $pb$Clase B en agarre en mojado$pb$, $pb$Marcaje 3PMSF homologado para nieve$pb$]::text[], array[$pb$Clase C en eficiencia energética$pb$, $pb$Sin ventaja de etiqueta sobre el resto de premium$pb$]::text[], $pb$[{"label":"Medida de referencia","value":"205/55 R16"},{"label":"Eficiencia energética (etiqueta UE)","value":"C"},{"label":"Agarre en mojado (etiqueta UE)","value":"B"},{"label":"Ruido exterior","value":"70 dB"},{"label":"Temporada","value":"Invierno"},{"label":"Marcaje 3PMSF","value":"Sí"}]$pb$::jsonb);
insert into guide_item_stores (guide_item_id, store, external_id, url, note, position)
values ((select i.id from guide_items i where i.guide_id = (select id from guides where slug = $pb$neumaticos-invierno$pb$) and i.position = 3), $pb$neumaticos$pb$, $pb$bridgestone-205-55-16-blizzak_6$pb$, $pb$https://www.neumaticos.es/neumaticos/bridgestone-205-55-16-blizzak_6/108+200+201+202+205$pb$, $pb$Precio para 205/55 R16$pb$, 0);
insert into guide_items (guide_id, position, name, award, summary_md, pros, cons, specs)
values ((select id from guides where slug = $pb$neumaticos-invierno$pb$), 4, $pb$Goodyear UltraGrip Performance 3$pb$, $pb$Alternativa equilibrada$pb$, $pb$El UltraGrip Performance 3 es la apuesta de invierno de Goodyear para turismos, y se sitúa entre el Bridgestone y el Continental en precio. Su etiqueta UE coincide con la de ambos: C en eficiencia energética, B en agarre en mojado y 70 dB. Lleva el marcaje 3PMSF. Tiene sentido si encuentras una bajada puntual o si tu taller habitual trabaja con la marca y te facilita el montaje. La pega: no aporta ventaja de etiqueta frente a los otros premium y su eficiencia se queda en C.$pb$, array[$pb$Marca premium a precio intermedio dentro de la lista$pb$, $pb$Clase B en agarre en mojado$pb$, $pb$Marcaje 3PMSF homologado para nieve$pb$]::text[], array[$pb$Clase C en eficiencia energética$pb$, $pb$Sin ventaja de etiqueta frente a sus rivales directos$pb$]::text[], $pb$[{"label":"Medida de referencia","value":"205/55 R16"},{"label":"Eficiencia energética (etiqueta UE)","value":"C"},{"label":"Agarre en mojado (etiqueta UE)","value":"B"},{"label":"Ruido exterior","value":"70 dB"},{"label":"Temporada","value":"Invierno"},{"label":"Marcaje 3PMSF","value":"Sí"}]$pb$::jsonb);
insert into guide_item_stores (guide_item_id, store, external_id, url, note, position)
values ((select i.id from guide_items i where i.guide_id = (select id from guides where slug = $pb$neumaticos-invierno$pb$) and i.position = 4), $pb$neumaticos$pb$, $pb$goodyear-205-55-16-ultragrip_performance_3$pb$, $pb$https://www.neumaticos.es/neumaticos/goodyear-205-55-16-ultragrip_performance_3/108+200+201+202+205$pb$, $pb$Precio para 205/55 R16$pb$, 0);
insert into guide_items (guide_id, position, name, award, summary_md, pros, cons, specs)
values ((select id from guides where slug = $pb$neumaticos-invierno$pb$), 5, $pb$Nexen Winguard Sport 2$pb$, $pb$La opción económica$pb$, $pb$Nexen es una marca de gama económica y el Winguard Sport 2 es, con diferencia, el más asequible de la guía. A cambio de ese ahorro, su etiqueta UE baja a una D en eficiencia energética, mientras que mantiene la B en agarre en mojado y los 70 dB de los modelos premium. Lleva el marcaje 3PMSF. Encaja si solo necesitas neumáticos de invierno para unas pocas salidas a la nieve al año y haces pocos kilómetros. La pega: la clase D, que se nota en el consumo, y la menor reputación de la marca.$pb$, array[$pb$El más asequible de la lista$pb$, $pb$Clase B en agarre en mojado, como los premium$pb$, $pb$Marcaje 3PMSF homologado para nieve$pb$]::text[], array[$pb$Clase D en eficiencia energética, la peor de la guía$pb$, $pb$Marca de gama económica$pb$]::text[], $pb$[{"label":"Medida de referencia","value":"205/55 R16"},{"label":"Eficiencia energética (etiqueta UE)","value":"D"},{"label":"Agarre en mojado (etiqueta UE)","value":"B"},{"label":"Ruido exterior","value":"70 dB"},{"label":"Temporada","value":"Invierno"},{"label":"Marcaje 3PMSF","value":"Sí"}]$pb$::jsonb);
