values ((select id from guides where slug = $pb$neumaticos-all-season$pb$), 1, $pb$Michelin CrossClimate 2$pb$, $pb$Mejor en general$pb$, $pb$Uno de los all-season de referencia de una marca premium, y en esta medida su etiqueta UE es la más redonda de la guía: B en eficiencia energética, B en agarre en mojado y 69 dB, el registro más bajo de la lista. Lleva el marcaje 3PMSF para nieve. Es la elección lógica si buscas un único juego para todo el año y no te importa pagar algo más por la marca. La pega: algunas variantes de esta medida bajan a C en eficiencia, así que revisa la etiqueta exacta antes de comprar.$pb$, array[$pb$69 dB, el más silencioso de la guía según la etiqueta$pb$, $pb$Clase B en eficiencia y en agarre en mojado$pb$, $pb$Marcaje 3PMSF homologado para nieve$pb$]::text[], array[$pb$Algunas variantes bajan a clase C en eficiencia$pb$, $pb$Precio de gama premium$pb$]::text[], $pb$[{"label":"Medida de referencia","value":"205/55 R16"},{"label":"Eficiencia energética (etiqueta UE)","value":"B (C en algunas variantes)"},{"label":"Agarre en mojado (etiqueta UE)","value":"B"},{"label":"Ruido exterior","value":"69 dB"},{"label":"Temporada","value":"All-season"},{"label":"Marcaje 3PMSF","value":"Sí"}]$pb$::jsonb);
