values ((select id from guides where slug = $pb$neumaticos-all-season$pb$), 2, $pb$Continental AllSeasonContact 2$pb$, $pb$Alternativa premium$pb$, $pb$La propuesta de cuatro estaciones de Continental iguala al Michelin en lo esencial de la etiqueta UE: B en eficiencia energética y B en agarre en mojado. Donde se queda atrás es en el ruido, con 71 dB en su variante principal. Lleva el marcaje 3PMSF. Es una buena opción si prefieres la marca alemana o si en tu medida exacta encuentras mejor precio que el del Michelin. La pega: es de los más ruidosos de la lista y algunas variantes bajan a C en eficiencia, aunque con 70 dB.$pb$, array[$pb$Clase B en eficiencia energética$pb$, $pb$Clase B en agarre en mojado$pb$, $pb$Marcaje 3PMSF homologado para nieve$pb$]::text[], array[$pb$71 dB en la variante principal$pb$, $pb$Algunas variantes bajan a clase C en eficiencia$pb$]::text[], $pb$[{"label":"Medida de referencia","value":"205/55 R16"},{"label":"Eficiencia energética (etiqueta UE)","value":"B (C en algunas variantes)"},{"label":"Agarre en mojado (etiqueta UE)","value":"B"},{"label":"Ruido exterior","value":"71 dB (70 dB en algunas variantes)"},{"label":"Temporada","value":"All-season"},{"label":"Marcaje 3PMSF","value":"Sí"}]$pb$::jsonb);
