values ((select id from guides where slug = $pb$neumaticos-all-season$pb$), 3, $pb$Bridgestone Turanza All Season 6$pb$, $pb$Mejor relación calidad-precio$pb$, $pb$Es uno de los all-season de marca premium con mejor precio en esta medida, y su etiqueta UE se mantiene en la media del grupo: C en eficiencia energética, B en agarre en mojado y 70 dB de ruido exterior. Lleva el marcaje 3PMSF, así que puedes usarlo en escapadas a la nieve. Tiene sentido si quieres un juego para todo el año de una marca de primera línea y te importa más el precio de compra que un pequeño ahorro de combustible. La pega: la clase C en eficiencia frente a la B de Michelin y Continental.$pb$, array[$pb$Marca premium a un precio contenido$pb$, $pb$Clase B en agarre en mojado$pb$, $pb$Marcaje 3PMSF homologado para nieve$pb$]::text[], array[$pb$Clase C en eficiencia energética$pb$, $pb$Sin ventaja de etiqueta frente a sus rivales$pb$]::text[], $pb$[{"label":"Medida de referencia","value":"205/55 R16"},{"label":"Eficiencia energética (etiqueta UE)","value":"C"},{"label":"Agarre en mojado (etiqueta UE)","value":"B"},{"label":"Ruido exterior","value":"70 dB"},{"label":"Temporada","value":"All-season"},{"label":"Marcaje 3PMSF","value":"Sí"}]$pb$::jsonb);
