values ((select id from guides where slug = $pb$neumaticos-all-season$pb$), 5, $pb$Hankook Kinergy 4S2$pb$, $pb$La opción de gama media$pb$, $pb$Hankook es una marca de gama intermedia que suele competir en precio con los premium más asequibles. En esta medida, el Kinergy 4S2 marca C en eficiencia energética, B en agarre en mojado y 72 dB, el ruido más alto de la guía. Lleva el marcaje 3PMSF. Es una alternativa razonable si encuentras una oferta clara o si tu taller trabaja habitualmente con la marca. La pega: su precio suele moverse muy cerca del Bridgestone, que tiene las mismas clases de eficiencia y agarre y es más silencioso, así que conviene comparar antes de decidir.$pb$, array[$pb$Marca intermedia con precio competitivo$pb$, $pb$Clase B en agarre en mojado$pb$, $pb$Marcaje 3PMSF homologado para nieve$pb$]::text[], array[$pb$72 dB, el más ruidoso de la guía según la etiqueta$pb$, $pb$Clase C en eficiencia energética$pb$]::text[], $pb$[{"label":"Medida de referencia","value":"205/55 R16"},{"label":"Eficiencia energética (etiqueta UE)","value":"C"},{"label":"Agarre en mojado (etiqueta UE)","value":"B"},{"label":"Ruido exterior","value":"72 dB"},{"label":"Temporada","value":"All-season"},{"label":"Marcaje 3PMSF","value":"Sí"}]$pb$::jsonb);
