values ((select id from guides where slug = $pb$neumaticos-furgoneta-215-65-r16c$pb$), 1, $pb$Michelin Agilis 3$pb$, $pb$Mejor en general$pb$, $pb$El neumático de furgoneta de Michelin, de gama premium y pensado para profesionales que hacen muchos kilómetros. Su etiqueta UE marca B en eficiencia energética y A en agarre en mojado, una combinación sólida para una furgoneta de trabajo. Es la opción a considerar si la furgoneta es tu herramienta diaria y prefieres pagar más de entrada a cambio de una marca de referencia. La pega: es el más caro de la guía y, con 72 dB, el más ruidoso según la etiqueta, algo que se nota en trayectos largos por autovía.$pb$, array[$pb$Clase A en agarre en mojado$pb$, $pb$Clase B en eficiencia energética$pb$, $pb$Marca premium con posicionamiento profesional$pb$]::text[], array[$pb$72 dB, el más ruidoso de la guía según la etiqueta$pb$, $pb$El más caro de la lista$pb$]::text[], $pb$[{"label":"Medida de referencia","value":"215/65 R16C"},{"label":"Eficiencia energética (etiqueta UE)","value":"B"},{"label":"Agarre en mojado (etiqueta UE)","value":"A"},{"label":"Ruido exterior","value":"72 dB"},{"label":"Temporada","value":"Verano"}]$pb$::jsonb);
