insert into guide_items (guide_id, position, name, award, summary_md, pros, cons, specs)
values ((select id from guides where slug = $pb$neumaticos-furgoneta-215-65-r16c$pb$), 2, $pb$Goodyear EfficientGrip Cargo 2$pb$, $pb$Mejor relación calidad-precio$pb$, $pb$En su variante principal es el único de la guía con doble A en la etiqueta UE: A en eficiencia energética y A en agarre en mojado, con 71 dB de ruido exterior. Y lo consigue por debajo del precio de Michelin, Continental y Bridgestone. Para una furgoneta que hace muchos kilómetros, esa clase A en eficiencia es un argumento de peso. La pega: hay variantes en esta medida con una etiqueta bastante peor, C en eficiencia y B en mojado, así que comprueba la etiqueta exacta de la versión que vas a comprar.$pb$, array[$pb$Clase A en eficiencia energética en la variante principal$pb$, $pb$Clase A en agarre en mojado$pb$, $pb$Marca premium por debajo del precio de sus rivales directos$pb$]::text[], array[$pb$Algunas variantes bajan a C en eficiencia y B en mojado$pb$, $pb$71 dB de ruido exterior$pb$]::text[], $pb$[{"label":"Medida de referencia","value":"215/65 R16C"},{"label":"Eficiencia energética (etiqueta UE)","value":"A (C en algunas variantes)"},{"label":"Agarre en mojado (etiqueta UE)","value":"A (B en algunas variantes)"},{"label":"Ruido exterior","value":"71 dB (70 o 72 dB según variante)"},{"label":"Temporada","value":"Verano"}]$pb$::jsonb);
insert into guide_item_stores (guide_item_id, store, external_id, url, note, position)
values ((select i.id from guide_items i where i.guide_id = (select id from guides where slug = $pb$neumaticos-furgoneta-215-65-r16c$pb$) and i.position = 2), $pb$neumaticos$pb$, $pb$goodyear-215-65-16-efficientgrip_cargo_2$pb$, $pb$https://www.neumaticos.es/neumaticos/goodyear-215-65-16-efficientgrip_cargo_2/108+200+201+202+205$pb$, $pb$Precio para 215/65 R16C$pb$, 0);
