values ((select id from guides where slug = $pb$neumaticos-furgoneta-215-65-r16c$pb$), 3, $pb$Bridgestone Duravis Van$pb$, $pb$El más silencioso según la etiqueta$pb$, $pb$Con 69 dB de ruido exterior comparte el registro más bajo de la guía con el Nexen, pero con el respaldo de una marca premium. El resto de su etiqueta UE también es buena: B en eficiencia energética y A en agarre en mojado. Es una opción muy coherente si usas la furgoneta también para viajes largos o como vehículo familiar y valoras ir con menos ruido de rodadura. La pega: su precio está a la altura del Continental, y en eficiencia no llega a la clase A del Goodyear.$pb$, array[$pb$69 dB, empatado como el más silencioso de la guía$pb$, $pb$Clase A en agarre en mojado$pb$, $pb$Clase B en eficiencia energética$pb$]::text[], array[$pb$Precio de gama premium$pb$, $pb$No llega a la clase A en eficiencia$pb$]::text[], $pb$[{"label":"Medida de referencia","value":"215/65 R16C"},{"label":"Eficiencia energética (etiqueta UE)","value":"B"},{"label":"Agarre en mojado (etiqueta UE)","value":"A"},{"label":"Ruido exterior","value":"69 dB"},{"label":"Temporada","value":"Verano"}]$pb$::jsonb);
