values ((select i.id from guide_items i where i.guide_id = (select id from guides where slug = $pb$neumaticos-furgoneta-215-65-r16c$pb$) and i.position = 3), $pb$neumaticos$pb$, $pb$bridgestone-215-65-16-duravis_van$pb$, $pb$https://www.neumaticos.es/neumaticos/bridgestone-215-65-16-duravis_van/108+200+201+202+205$pb$, $pb$Precio para 215/65 R16C$pb$, 0);
