values ((select id from guides where slug = $pb$neumaticos-furgoneta-215-65-r16c$pb$), 4, $pb$Continental VanContact Ultra$pb$, $pb$Alternativa premium$pb$, $pb$El modelo de furgoneta de Continental tiene una etiqueta UE muy equilibrada: B en eficiencia energética, A en agarre en mojado y 71 dB de ruido exterior. Se mueve en un precio parecido al del Bridgestone, por lo que la elección entre ambos suele decidirla la oferta del momento o la preferencia de marca. Es una opción sensata para quien quiere una marca de primera línea sin irse al precio del Michelin. La pega: no destaca en ningún apartado de la etiqueta frente a sus rivales directos.$pb$, array[$pb$Clase A en agarre en mojado$pb$, $pb$Clase B en eficiencia energética$pb$, $pb$Marca premium por debajo del precio del Michelin$pb$]::text[], array[$pb$Sin ventaja de etiqueta sobre sus rivales directos$pb$, $pb$71 dB de ruido exterior$pb$]::text[], $pb$[{"label":"Medida de referencia","value":"215/65 R16C"},{"label":"Eficiencia energética (etiqueta UE)","value":"B"},{"label":"Agarre en mojado (etiqueta UE)","value":"A"},{"label":"Ruido exterior","value":"71 dB"},{"label":"Temporada","value":"Verano"}]$pb$::jsonb);
