values ((select id from guides where slug = $pb$neumaticos-furgoneta-215-65-r16c$pb$), 5, $pb$Nexen Roadian CT8$pb$, $pb$La opción económica$pb$, $pb$Nexen es una marca de gama económica y el Roadian CT8 es, con diferencia, el más asequible de la guía. Su etiqueta UE sorprende para lo que cuesta: A en agarre en mojado y 69 dB, empatado con el Bridgestone como el más silencioso. Donde cede es en eficiencia energética, con una C. Encaja en una furgoneta particular o de uso ocasional que no hace tantos kilómetros. La pega: esa clase C se traduce en algo más de consumo, y en un uso profesional intensivo puede compensar más un modelo con mejor eficiencia.$pb$, array[$pb$El más asequible de la lista$pb$, $pb$Clase A en agarre en mojado$pb$, $pb$69 dB, empatado como el más silencioso de la guía$pb$]::text[], array[$pb$Clase C en eficiencia, la más baja entre las variantes principales$pb$, $pb$Marca de gama económica$pb$]::text[], $pb$[{"label":"Medida de referencia","value":"215/65 R16C"},{"label":"Eficiencia energética (etiqueta UE)","value":"C"},{"label":"Agarre en mojado (etiqueta UE)","value":"A"},{"label":"Ruido exterior","value":"69 dB"},{"label":"Temporada","value":"Verano"}]$pb$::jsonb);
